import pytest
from decimal import Decimal, getcontext, InvalidOperation
from app.discount_eval import apply_discount

getcontext().prec = 28

def test_apply_discount_normal_case():
    result = apply_discount('100.00', '0.25')
    assert result == '75.00'

def test_apply_discount_zero_rate():
    result = apply_discount('100.00', '0.00')
    assert result == '100.00'

def test_apply_discount_one_rate():
    result = apply_discount('100.00', '1.00')
    assert result == '0.00'

def test_apply_discount_invalid_amount():
    with pytest.raises(ValueError):
        apply_discount('-100.00', '0.25')

def test_apply_discount_invalid_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', '1.25')

def test_apply_discount_non_finite_amount():
    with pytest.raises(ValueError):
        apply_discount('NaN', '0.25')

def test_apply_discount_non_finite_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', 'NaN')

def test_apply_discount_boundary_cases():
    # Test boundary values for rate (0.00, 1.00)
    assert apply_discount('100.00', '0.00') == '100.00'
    assert apply_discount('100.00', '1.00') == '0.00'

def test_apply_discount_rounding():
    result = apply_discount('100.00', '0.16666666666666666')
    assert result == '83.34'

def test_apply_discount_malformed_numeric_text_amount():
    with pytest.raises(ValueError):
        apply_discount('100.00.00', '0.25')

def test_apply_discount_malformed_numeric_text_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', '0.25.00')

def test_apply_discount_empty_amount():
    with pytest.raises(ValueError):
        apply_discount('', '0.25')

def test_apply_discount_empty_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', '')

def test_apply_discount_missing_amount():
    with pytest.raises(ValueError):
        apply_discount(None, '0.25')

def test_apply_discount_missing_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', None)

def test_apply_discount_fractional_vs_int_amount():
    result = apply_discount('100.00', '0.50')
    assert result == '50.00'

def test_apply_discount_fractional_vs_int_rate():
    result = apply_discount('100.00', '0.50')
    assert result == '50.00'

def test_apply_discount_boolean_vs_int_amount():
    with pytest.raises(ValueError):
        apply_discount('True', '0.25')

def test_apply_discount_boolean_vs_int_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', 'True')

def test_apply_discount_inf_amount():
    with pytest.raises(ValueError):
        apply_discount('inf', '0.25')

def test_apply_discount_inf_rate():
    with pytest.raises(ValueError):
        apply_discount('100.00', 'inf')

def test_apply_discount_rounding_boundaries():
    result = apply_discount('100.00', '0.16666666666666666')
    assert result == '83.34'
    result = apply_discount('100.00', '0.16666666666666667')
    assert result == '83.33'

